   const pages=(options.pagesBySearch?.[stages().filter(s=>s==='flipcheck_catalogue_search').length-1]||d.pages||[]).filter(p=>p.url),web=kind==='flipcheck_catalogue_search'&&body.tools?.some(t=>t.type==='web_search')?pages.map(p=>({...p,source_text:p.source_text||p.text||'',snippet:p.text||p.source_text||''})):[];
   const reply=envelope(payload,kind==='flipcheck_card_market'?(options.cardMarketSources||[]):web),record=options.recordedPhases?.find(p=>p.stage===({flipcheck_identification:'vision',flipcheck_catalogue_search:'flipcheck_catalogue_search'})[kind]);if(record?.usage&&(kind!=='flipcheck_catalogue_search'||body.tools?.some(t=>t.type==='web_search'))){reply.usage=record.usage;if(record.webCalls===2&&web.length)reply.output.unshift({...reply.output[0]});}
