test('233 Ximilar selection sends one photo and no Lens request; token stays out of diagnostics and storage',async()=>{await reset('politoed',{ximilar:true,lens:true,ximilarReply:ximilarPolitoed233,bandObservations:politoedKeys204});const out=await scan(),calls=native.filter(n=>n.action==='ximilar');assert.equal(calls.length,1);assert.equal(calls[0].endpoint,'tcg_id');assert.ok(calls[0].image_base64);assert.equal(native.filter(n=>n.action.startsWith('lens')).length,0);assert.equal(out.visualAssistance.ximilar.state,'ok');assert.equal(out.visualAssistance.ximilar.entries[0].number,'H23/H32');assert.ok(out.visualAssistance.budget.entries.some(e=>e.kind==='ximilar'&&e.reservedUsd===.0069));assert.ok(!JSON.stringify(out).includes('test-ximilar-token'));assert.ok(!await page.evaluate(()=>JSON.stringify(localStorage).includes('test-ximilar-token')));assert.equal(out.identification.physical_card_number,'H23/H32');await page.goto(origin);assert.equal(await page.locator('#cardProvider233').inputValue(),'ximilar');assert.equal(await page.locator('#ximilarToken233').inputValue(),'');});
for(const [status,state] of [[401,'authentication_failed'],[403,'access_denied'],[429,'quota_or_rate_limit']])test('233 Ximilar '+status+' is explained and falls back without another paid provider',async()=>{await reset('politoed',{ximilar:true,lens:true,ximilarReply:{status,body:{detail:'provider error'}},bandObservations:politoedKeys204});const out=await scan();assert.equal(out.visualAssistance.ximilar.state,state);assert.equal(native.filter(n=>n.action==='ximilar').length,1);assert.equal(native.filter(n=>n.action.startsWith('lens')).length,0);assert.equal(out.visualAssistance.budget.entries.find(e=>e.kind==='ximilar').actualUsd,0);assert.ok(await page.locator('#ximilarStatus233').innerText());});
test('233 no Ximilar token sends no Ximilar request',async()=>{await reset('politoed',{ximilar:true,noXimilarToken:true,bandObservations:politoedKeys204});const out=await scan();assert.equal(out.visualAssistance.ximilar.state,'not_configured');assert.equal(native.filter(n=>n.action==='ximilar').length,0);});
test('233 insufficient budget prevents Ximilar upload',async()=>{await reset('politoed',{ximilar:true});const result=await page.evaluate(async()=>{const ctx=newContext164();scan164=ctx;ctx.budget.reserve('vision',.029);const l=new E193.Ledger({domain:'pokemon',image_views:[{view:'front',certainty:'clear',image_index:1}]});await recognizeXimilar233(l,ctx);return ctx.ximilar;});assert.equal(result.state,'budget_exhausted');assert.equal(native.filter(n=>n.action==='ximilar').length,0);});
test('235 recognition prices render automatically and raw and PSA remain separate',async()=>{
 const reply=structuredClone(ximilarPolitoed233);reply.body.records[0]._objects[0]._identification.best_match.price_stats=[{stats_type:'ungraded',interval:'overall',value:{median:59.99,q1:39.99,q3:79.99,volume:25,latest_date:'2026-08-15'}},{stats_type:'graded',interval:'overall',value:{median:249.99}}];
 await reset('politoed',{ximilar:true,ximilarReply:reply,bandObservations:politoedKeys204});const out=await scan();assert.equal(native.filter(n=>n.action==='ximilar').length,1);assert.match(await page.locator('#cardMarket236').innerText(),/Valore non determinabile/);assert.doesNotMatch(await page.locator('#cardMarket236').innerText(),/59,99|249,99/);assert.equal(out.identification.price_summary.stat.currency,null);assert.equal(out.identification.market_ready,true);assert.doesNotMatch(await page.locator('#identPanel').innerText(),/undefined/);assert.equal(await page.locator('#marketBtn').innerText(),'CERCA VENDITE COMPARABILI');await page.locator('#identPanel').screenshot({path:'/tmp/flipcheck235-raw.png'});
 const before=native.length;await page.evaluate(()=>renderIdent({...ident,grading:{company:'PSA',grade:'8'}}));assert.match(await page.locator('#cardMarket236').innerText(),/PSA 8/);assert.doesNotMatch(await page.locator('#cardMarket236').innerText(),/59,99|249,99/);assert.equal(native.length,before);await page.locator('#identPanel').screenshot({path:'/tmp/flipcheck235-slab.png'});
});
test('235 selected Ximilar adds one pricing request to slab label route without changing grade',async()=>{await reset('psa',{ximilar:true});const out=await scan();assert.equal(out.identification.market_ready,true);assert.equal(native.filter(n=>n.action==='ximilar').length,1);assert.equal(out.visualAssistance.route,'slab_label');assert.match(await page.locator('#cardMarket236').innerText(),/Valore non determinabile/);assert.match(await page.locator('#cardMarket236').innerText(),/PSA/);assert.equal(out.identification.price_summary.stat,null);});

test('236 real Hill closes from print and web sold lookup keeps 1/1 with no comps',async()=>{
 const h=require('./fixtures/physical-236-hill.json'),source='https://www.sportscardspro.com/game/football-cards-2025-bowman-university-chrome/anthony-hill-jr-superfractor-bca-ahj';
 await reset('politoed',{packet:h.vision,photoCount:2,noOcr:true,ximilar:true,ximilarReply:{status:200,body:{status:{code:200},records:[{_status:{code:200},_objects:[{name:'Card',_identification:{best_match:{name:'Anthony Hill Jr.',set:'Bowman University Chrome',card_number:'BCA-AHJ',year:2025,manufacturer:'Topps',sub_set:'Tie dye'}}}]}]}},cardMarketReply:{access:'readable',page_url:source,page_title:'Anthony Hill Jr Superfractor',guide:{price:999,currency:'USD',label:'Ungraded',quote:'Ungraded 999'},sales:[]},cardMarketSources:[{url:source,title:'Anthony Hill Jr Superfractor'}]});
 const out=await scan();assert.equal(out.identification.market_ready,true);assert.equal(out.identification.derived_serial.value,'1/1');assert.equal(native.find(n=>n.action==='ximilar').price_stats,false);
 await page.locator('#marketBtn').click();await page.waitForFunction(()=>!apiBusy);const body=api.find(b=>b.text.format.name==='flipcheck_card_market');assert.ok(body);assert.deepEqual(body.tools[0].filters.allowed_domains,['sportscardspro.com']);assert.match(body.input,/Superfractor/);assert.equal(await page.evaluate(()=>ident.card_market.state),'one_of_one_no_sales');assert.match(await page.locator('#cardMarket236').innerText(),/nessuna vendita comparabile/);assert.doesNotMatch(await page.locator('#cardMarket236').innerText(),/999/);await page.locator('#identPanel').screenshot({path:'/tmp/flipcheck236-one-of-one.png'});
});

test('236 sold lookup renders raw median, excludes wrong parallel and allows explicit refresh',async()=>{
 const source='https://www.sportscardspro.com/game/basketball-cards-2018-panini-prizm/luka-doncic-green-prizm-280',date=new Date().toISOString().slice(0,10);
 const sales=[100,150,200,900].map((price,n)=>({source_url:source,url:'https://www.ebay.com/itm/'+(100000000000+n),title:'2018 Luka Doncic Green Prizm #280 English',quote:date+' Sold $'+price,date,price,currency:'USD',price_kind:'sold',subject:'Luka Doncic',set:'Panini Prizm',year:'2018',number:'280',subset:'',variant:n===3?'Green Pulsar':'Green Prizm',language:'en',edition:'',shadow:'',autograph:'',print_run:null,condition:'',grading:'raw',grader:'',grade:''}));
 await reset('politoed',{cardMarketReply:{access:'readable',page_url:source,page_title:'Luka Doncic [Green Prizm] #280',guide:{price:null,currency:'',label:'',quote:''},sales},cardMarketSources:[{url:source,title:'Luka Doncic'}]});
 await page.evaluate(()=>{ident={kind:'card',title:'Luka Doncic',category:'Basketball card',market_ready:true,exact_identity_status:'confirmed',card_identity:{subject:'Luka Doncic',set:'Panini Prizm',number:'280',date:'2018-19',variant:'Green Prizm',language:'en'}};scan164=newContext164();scan164.identityState='confirmed';trial={credits:3,free:false,attempts:0};$('scanBudget').value='.20';scan164.budget.targetUsd=.22;renderIdent(ident);});
 await page.locator('#marketBtn').click();await page.waitForFunction(()=>!apiBusy);assert.equal(await page.evaluate(()=>ident.card_market.stat.median),150);assert.equal(await page.evaluate(()=>scan164.comparablesState),'raw_condition_unspecified');assert.match(await page.locator('#cardMarket236').innerText(),/150,00/);assert.doesNotMatch(await page.locator('#cardMarket236').innerText(),/900,00/);await page.locator('#identPanel').screenshot({path:'/tmp/flipcheck236-comparables.png'});
 await page.locator('#marketBtn').click();await page.waitForFunction(()=>!apiBusy);assert.equal(stages().filter(x=>x==='flipcheck_card_market').length,2);assert.equal(await page.evaluate(()=>ident.card_market.stat.median),150);
 await page.evaluate(()=>scan164.budget.targetUsd=scan164.budget.spent()+.001);await page.locator('#marketBtn').click();await page.waitForFunction(()=>!apiBusy);assert.equal(stages().filter(x=>x==='flipcheck_card_market').length,2);assert.equal(await page.evaluate(()=>ident.card_market.state),'budget_exhausted');assert.equal(await page.evaluate(()=>ident.market_ready),true);
});
